// the thin frame panels use the same look, just without widget backgrounds
var EDGE_COLORIZER = JSON.parse(JSON.stringify(BAR_COLORIZER));
EDGE_COLORIZER.widgets.normal.enabled = false;
var BLANK_ICON = "@HOME@/.local/share/chromatia/blank.svg";
var FIRST_WALLPAPER = "@WALL@";      // set by install.sh, may be empty

var primary = 0;
panels().forEach(function (p) { if (p.screen === primary) p.remove(); });

function colorize(panel, settings, islands) {
    var c = panel.addWidget("luisbocanegra.panel.colorizer");
    c.currentConfigGroup = ["General"];
    c.writeConfig("globalSettings", JSON.stringify(settings));
    c.writeConfig("hideWidget", true);
    if (islands) {
        c.writeConfig("islandsEnabled", true);
        c.writeConfig("islandSeparatorWidget", "org.kde.plasma.panelspacer");
    }
    return c;
}
function edgePanel(location) {
    var p = new Panel("org.kde.panel");
    p.location = location; p.height = 12; p.lengthMode = "fill";
    p.floating = false; p.hiding = "none"; p.opacity = "adaptive";
    colorize(p, EDGE_COLORIZER, false);
    return p;
}
var known = knownWidgetTypes;
function has(t) { return known.indexOf(t) >= 0; }

// bottom island bar
var bar = new Panel("org.kde.panel");
bar.location = "bottom"; bar.height = 42; bar.lengthMode = "fill";
bar.floating = false; bar.hiding = "none"; bar.opacity = "translucent";
bar.addWidget("chromatia.workspaces");
colorize(bar, BAR_COLORIZER, true);
bar.addWidget("org.kde.plasma.panelspacer");
bar.addWidget("chromatia.folders");
bar.addWidget("org.kde.plasma.panelspacer");
bar.addWidget("chromatia.dock");
// two spacers on the right balance the two left of the dock, so it stays (almost) centered
bar.addWidget("org.kde.plasma.panelspacer");
bar.addWidget("org.kde.plasma.panelspacer");
if (has("org.kde.netspeedWidget")) {
    var ns = bar.addWidget("org.kde.netspeedWidget");
    ns.currentConfigGroup = ["General"]; ns.writeConfig("fontSize", 70);
}
var tray = bar.addWidget("org.kde.plasma.systemtray");
// KDE's bell keeps running (it powers the notifications) but hides in the tray: Chromatia shows them
tray.currentConfigGroup = ["General"];
tray.writeConfig("hiddenItems", ["org.kde.plasma.notifications"]);
bar.addWidget("chromatia.showdesktop");
var clock = bar.addWidget("org.kde.plasma.digitalclock");
clock.currentConfigGroup = ["Appearance"];
clock.writeConfig("autoFontAndSize", false);
clock.writeConfig("boldText", true);
clock.writeConfig("dateDisplayFormat", "BesideTime");
clock.writeConfig("dateFormat", "custom");
clock.writeConfig("customDateFormat", "ddd d MMM  ·  ");
clock.writeConfig("fontSize", 10);
clock.writeConfig("fontWeight", 700);

// top: dashboard (+ invisible launcher, opened by the bottom-left hot corner)
var top = edgePanel("top");
var kd = top.addWidget("org.kde.plasma.kickerdash");
kd.currentConfigGroup = ["General"]; kd.writeConfig("icon", BLANK_ICON);
top.addWidget("chromatia.dashboard");

// left: wallpaper gallery
var left = edgePanel("left");
left.addWidget("chromatia.wallpaperpanel");

// right: just the frame
edgePanel("right");

// desktop: Chromatia wallpaper on every screen, big clock on the primary one
desktops().forEach(function (d) {
    d.wallpaperPlugin = "chromatia.wallpaper";
    d.currentConfigGroup = ["Wallpaper", "chromatia.wallpaper", "General"];
    d.writeConfig("VisualizerEnabled", d.screen === primary);
    if (!d.readConfig("Image") && FIRST_WALLPAPER) d.writeConfig("Image", "file://" + FIRST_WALLPAPER);
    if (d.screen === primary) {
        var hasClock = d.widgets().some(function (w) { return w.type === "chromatia.clock"; });
        if (!hasClock) d.addWidget("chromatia.clock", 16, 16, 432, 144);
    }
});
print("Chromatia layout applied");
